#include <iostream>
#include <string>
#include <string_view>

class GeometricObject {
private:
    std::string color{"white"};
    bool filled{false};

protected:
    GeometricObject() = default;
    GeometricObject(std::string_view c, bool f) : color(c), filled(f) {}

public:
    virtual ~GeometricObject() = default;

    std::string getColor() const { return color; }
    void setColor(std::string_view c) { color = c; }
    bool isFilled() const { return filled; }
    void setFilled(bool f) { filled = f; }
    virtual std::string toString() const { return "Geometric Object"; }

    // Pure virtual functions make this class abstract
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
};

class Circle : public GeometricObject {
private:
    double radius{1.0};

public:
    Circle() = default;
    explicit Circle(double r) : radius(r >= 0 ? r : 0) {}
    Circle(double r, std::string_view c, bool f)
        : GeometricObject(c, f), radius(r >= 0 ? r : 0) {}

    double getRadius() const { return radius; }
    void setRadius(double r) { radius = (r >= 0) ? r : 0; }
    double getDiameter() const { return 2 * radius; }

    double getArea() const override {
        return radius * radius * 3.14159;
    }

    double getPerimeter() const override {
        return 2 * radius * 3.14159;
    }
};

class Rectangle : public GeometricObject {
private:
    double width{1.0};
    double height{1.0};

public:
    Rectangle() = default;
    Rectangle(double w, double h)
        : width(w >= 0 ? w : 0), height(h >= 0 ? h : 0) {}
    Rectangle(double w, double h, std::string_view c, bool f)
        : GeometricObject(c, f), width(w >= 0 ? w : 0), height(h >= 0 ? h : 0) {}

    double getWidth() const { return width; }
    void setWidth(double w) { width = (w >= 0) ? w : 0; }
    double getHeight() const { return height; }
    void setHeight(double h) { height = (h >= 0) ? h : 0; }

    double getArea() const override {
        return width * height;
    }

    double getPerimeter() const override {
        return 2 * (width + height);
    }
};

int main() {
    Circle c(2.5, "red", true);
    Rectangle r(4.0, 5.0, "blue", false);

    std::cout << "Circle radius: " << c.getRadius() << ", area: " << c.getArea() << "\n";
    std::cout << "Rectangle area: " << r.getArea() << ", perimeter: " << r.getPerimeter() << "\n";

    return 0;
}
